// Public fictional profile simulations; original histories remain unchanged.
export const coverage050Responses={"life-006":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-52737d6e141bd9","response":"unsure","confidence":"low","evidence":"Noah makes electronic sounds and mixes audio layers, but his stated creative interests do not include drawing, digital modeling, or making successive animation images. The creature scene alone cannot supply a preference for that visual work.","biographyPaths":["biography.currentLife.enjoys[1]","biography.currentLife.demonstratedSkills[1]","biography.timeline[5].story"],"constructSupport":"unknown","modelId":"life-006","phase":"development","careerId":"animation","questionId":"animation-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to create drawings or digital models that become moving characters, objects, or visual effects for animation as a regular part of your work?"},{"token":"reflection-f80e0b5d159cb2","response":"unsure","confidence":"low","evidence":"He experiments with sound and used teammates’ conflicting suggestions on an unfinished track. That supports creative revision in audio; it leaves open whether he would enjoy repeatedly planning and adjusting visual movement to communicate an action.","biographyPaths":["biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.activities[1]"],"constructSupport":"plausible","modelId":"life-006","phase":"development","careerId":"animation","questionId":"animation-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to plan animated scenes and revise their movement, timing, or appearance to make the intended action clear as a regular part of your work?"}]},"life-024":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-1d837f9f7aef47","response":"unsure","confidence":"low","evidence":"Samuel repeatedly sketches remembered rooms and enjoys poetry about ordinary details, giving him material for related artwork. There is no stated wish to assemble a connected collection or make audience-facing presentation decisions, so personal image making does not settle this reflection.","biographyPaths":["biography.timeline[3].story","biography.timeline[5].story","biography.currentLife.enjoys[1]","biography.currentLife.enjoys[2]"],"constructSupport":"plausible","modelId":"life-024","phase":"development","careerId":"degree-27101300","questionId":"degree-27101300-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to develop a coherent personal body of artwork and make considered choices about how it is finished, presented, or adapted for an audience?"},{"token":"reflection-25ea65b5d4fa7e","response":"unsure","confidence":"low","evidence":"He helps restore donated furniture, enjoys learning the techniques, and patiently prepares surfaces. Those are concrete interests in material work on existing objects, but preserving original evidence for future study rather than restoring usefulness or appearance is not established.","biographyPaths":["biography.timeline[5].story","biography.currentLife.enjoys[0]","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"life-024","phase":"development","careerId":"degree-25401300","questionId":"degree-25401300-047-domain","expanded":true,"originalPrompt":"Would you like to learn to preserve artworks, historical objects, or scientific specimens so their materials and significant features remain available for future study and display?"},{"token":"reflection-c1c748898a7a01","response":"unsure","confidence":"low","evidence":"His donation workshop and patience with furniture preparation offer a possible link to protective object care. His personal notebook and preference for dependable plans do not establish a wish to record conservation interventions or specify storage and handling to prevent future damage.","biographyPaths":["biography.currentLife.activities[1]","biography.currentLife.activities[2]","biography.currentLife.demonstratedSkills[1]","biography.selfDescription"],"constructSupport":"plausible","modelId":"life-024","phase":"development","careerId":"degree-25401300","questionId":"degree-25401300-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to document conservation work carefully and recommend storage or handling conditions that reduce damage without unnecessarily altering the object?"}]},"life-027":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-e12087b9422bb3","response":"unsure","confidence":"low","evidence":"Cora enjoys essays, word puzzles, and discussions around shared texts. Nothing in those activities states an interest in conveying another person’s message between languages; English at home is not evidence of either dislike or inability to learn it.","biographyPaths":["biography.background.cultureLanguages","biography.timeline[3].story","biography.timeline[5].story","biography.currentLife.enjoys[0]"],"constructSupport":"unknown","modelId":"life-027","phase":"development","careerId":"interpreting","questionId":"interpreting-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to convey someone’s spoken or signed message accurately from one language into another?"},{"token":"reflection-4aa5078ad9ff5d","response":"unsure","confidence":"low","evidence":"She likes performing characters, understands character motivations, and discusses essays that challenge familiar opinions. These provide a possible interest in intended meaning, but they do not show whether working out tone specifically across languages would appeal.","biographyPaths":["biography.timeline[2].story","biography.timeline[4].story","biography.currentLife.demonstratedSkills[2]"],"constructSupport":"plausible","modelId":"life-027","phase":"development","careerId":"interpreting","questionId":"interpreting-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to work out meaning and context across languages so the translated message preserves the speaker’s intent and tone?"}]},"life-030":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-4d08f0d0cf8ac2","response":"yes","confidence":"medium","evidence":"Theo has repeatedly chosen theater scenery work since enjoying painting a production backdrop, willingly explained his color choices, and still volunteers with local theater. His early invented shops and characters, practical problem solving, and motivation to learn through repeated trials together support wanting to learn how to turn a story into workable spatial plans and revise them, even though detailed models would be new.","biographyPaths":["biography.timeline[0].story","biography.timeline[2].story","biography.timeline[3].story","biography.timeline[5].story","biography.currentLife.activities[1]","biography.currentLife.motivations[1]"],"constructSupport":"direct","modelId":"life-030","phase":"development","careerId":"degree-27102700","questionId":"degree-27102700-047-method","expanded":true,"originalPrompt":"Would you like to learn to translate a script or exhibition purpose into spatial drawings and models, then revise the design around practical production constraints?"},{"token":"reflection-21dfb7d6097166","response":"unsure","confidence":"low","evidence":"He enjoys scene painting, mixing colors, and inventing characters. That supplies visual and story interests, but creating a character through successive moving images is a different method from a painted stage backdrop, and no preference for it is stated.","biographyPaths":["biography.timeline[0].story","biography.timeline[2].story","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"life-030","phase":"development","careerId":"animation","questionId":"animation-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to create drawings or digital models that become moving characters, objects, or visual effects for animation as a regular part of your work?"},{"token":"reflection-42742d3c8c1588","response":"unsure","confidence":"low","evidence":"His theater participation connects him with stories and visual choices, while repeated sound trials show willingness to experiment. Neither describes planning animated action or revising its timing and movement, so the transfer remains tentative.","biographyPaths":["biography.timeline[5].story","biography.currentLife.activities[1]","biography.currentLife.motivations[1]"],"constructSupport":"plausible","modelId":"life-030","phase":"development","careerId":"animation","questionId":"animation-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to plan animated scenes and revise their movement, timing, or appearance to make the intended action clear as a regular part of your work?"}]},"life-045":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-9438ec71ce278d","response":"unsure","confidence":"low","evidence":"Caleb asks clarifying questions while helping his grandfather with forms, but that is practical help in a familiar context. His biography does not state a wish to carry spoken or signed messages between languages, and the scene does not create one.","biographyPaths":["biography.timeline[6].story","biography.currentLife.activities[2]","biography.currentLife.demonstratedSkills[2]","biography.background.cultureLanguages"],"constructSupport":"unknown","modelId":"life-045","phase":"development","careerId":"interpreting","questionId":"interpreting-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to convey someone’s spoken or signed message accurately from one language into another?"},{"token":"reflection-35130f1744d2d7","response":"unsure","confidence":"low","evidence":"He noticed different versions and missing details when discussing family photographs and stories. That supports attention to contextual meaning, but there is no evidence that interpreting intent and tone across languages is itself appealing to him.","biographyPaths":["biography.timeline[3].story","biography.currentLife.enjoys[1]"],"constructSupport":"plausible","modelId":"life-045","phase":"development","careerId":"interpreting","questionId":"interpreting-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to work out meaning and context across languages so the translated message preserves the speaker’s intent and tone?"},{"token":"reflection-61513de97e626f","response":"unsure","confidence":"low","evidence":"Caleb’s sustained creative activity is guitar playing with friends; formal visual art is listed among unfamiliar activities. His childhood arranged vehicle play does not establish an interest in making drawings or models into animated characters, and unfamiliar visual practice alone is not a negative preference.","biographyPaths":["biography.timeline[1].story","biography.timeline[5].story","biography.currentLife.unfamiliarActivities[2]"],"constructSupport":"unknown","modelId":"life-045","phase":"development","careerId":"animation","questionId":"animation-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to create drawings or digital models that become moving characters, objects, or visual effects for animation as a regular part of your work?"},{"token":"reflection-07efe5e08c7936","response":"unsure","confidence":"low","evidence":"Keeping rhythm and making music sound right together could make timing choices relatable. His weekly music group and self-description concern sound rather than planning and repeatedly revising visual scenes, leaving the animation interest unresolved.","biographyPaths":["biography.timeline[5].story","biography.currentLife.demonstratedSkills[0]","biography.selfDescription"],"constructSupport":"plausible","modelId":"life-045","phase":"development","careerId":"animation","questionId":"animation-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to plan animated scenes and revise their movement, timing, or appearance to make the intended action clear as a regular part of your work?"}]},"life-056":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-008bb3ce3929d6","response":"unsure","confidence":"low","evidence":"Chinedu voluntarily helps younger dancers learn a transition and tries alternative explanations, so teaching within the arts is more than a generic helping motive for him. The biography does not establish interest in adult beginners or in developing their expression and creative choices through the listed visual, dramatic, or musical media.","biographyPaths":["biography.timeline[5].story","biography.currentLife.enjoys[2]","biography.currentLife.activities[0]"],"constructSupport":"plausible","modelId":"life-056","phase":"development","careerId":"degree-25112100","questionId":"degree-25112100-047-domain","expanded":true,"originalPrompt":"Would you like to learn to teach adult learners to develop artistic expression through visual art, drama, or music while understanding the choices behind creative work?"},{"token":"reflection-99e52bbc91f7e6","response":"yes","confidence":"high","evidence":"When younger dancers struggled with a transition, Chinedu recognized that describing his own sensation was inadequate, tried several explanations, and watched which changed their next attempt. Together with his continuing ensemble participation and stated enjoyment of teaching several ways, this directly supports learning to evaluate a performance and give actionable feedback that develops the learner.","biographyPaths":["biography.timeline[5].story","biography.currentLife.activities[0]","biography.currentLife.enjoys[2]","biography.currentLife.demonstratedSkills[2]"],"constructSupport":"direct","modelId":"life-056","phase":"development","careerId":"degree-25112100","questionId":"degree-25112100-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to evaluate students' creative work or performances and provide constructive feedback that supports their development rather than merely expressing personal taste?"}]},"life-067":{"version":"0.50.0","phase":"development","answers":[{"token":"reflection-3efc79d5ed8fcd","response":"unsure","confidence":"low","evidence":"Greta enjoyed labeled classroom trays, sorting donations, and arranging garage-sale supplies. Those repeated choices support making shared materials findable, but they do not establish interest in the full electronic record lifecycle, including capture, sharing, and disposal.","biographyPaths":["biography.timeline[2].story","biography.timeline[4].story","biography.timeline[5].story","biography.currentLife.enjoys[0]"],"constructSupport":"plausible","modelId":"life-067","phase":"development","careerId":"degree-15129903","questionId":"degree-15129903-047-domain","expanded":true,"originalPrompt":"Would you like to learn to organize how an organization captures, stores, finds, shares, and eventually disposes of its electronic documents and records?"},{"token":"reflection-b1e013eae5f17d","response":"unsure","confidence":"low","evidence":"She likes usable spaces and clear labels and continues helping with service-club supplies. The scene’s central responsibility is choosing record access, confidentiality, retention, and disposal rules; her supply organization does not indicate a preference for those judgments.","biographyPaths":["biography.currentLife.activities[0]","biography.currentLife.demonstratedSkills[0]","biography.timeline[2].story"],"constructSupport":"plausible","modelId":"life-067","phase":"development","careerId":"degree-15129903","questionId":"degree-15129903-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to coordinate document-handling rules that balance useful access with confidentiality, retention duties, and secure disposal when records are no longer needed?"}]},"gap-005":{"version":"0.50.0","phase":"supplement","answers":[{"token":"reflection-03199c1cedf0a8","response":"unsure","confidence":"low","evidence":"Priya enjoys timing laps accurately and following clear practiced safety sequences. These connect with orderly measurements and consistent procedures, but her activities and next-step training wish concern swimming and pool safety, not supporting statistical studies.","biographyPaths":["biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.enjoys[2]","biography.currentLife.demonstratedSkills[0]"],"constructSupport":"plausible","modelId":"gap-005","phase":"supplement","careerId":"degree-43911100","questionId":"degree-43911100-047-domain","expanded":true,"originalPrompt":"Would you like to learn to support statistical studies by organizing information and carrying out calculations using established statistical procedures accurately and consistently?"},{"token":"reflection-9cf8e4645db8c4","response":"unsure","confidence":"low","evidence":"Accurate lap timing and her recognition that knowing safety steps differs from making oneself heard could transfer to careful communication. There is no expressed interest in maintaining study calculation histories or explaining uncertain research results for team review.","biographyPaths":["biography.timeline[4].story","biography.currentLife.demonstratedSkills[0]","biography.currentLife.activities[2]"],"constructSupport":"plausible","modelId":"gap-005","phase":"supplement","careerId":"degree-43911100","questionId":"degree-43911100-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to maintain reliable study records and explain calculation results clearly while recognizing errors or uncertainties that need review by the research team?"}]},"gap-006":{"version":"0.50.0","phase":"supplement","answers":[{"token":"reflection-62e4ac67961f02","response":"unsure","confidence":"low","evidence":"Mateo enjoys crossing off receipt tasks, once entered fictional purchases for fun, now reconciles small purchase lists and flags omissions for an adult. This gives a real financial-record connection, but the biography explicitly leaves open whether he would enjoy more complex record work; analyzing organizational reports and learning reporting obligations remains uncertain.","biographyPaths":["biography.timeline[2].story","biography.timeline[4].story","biography.timeline[6].story","biography.openQuestions[0]","biography.openQuestions[1]"],"constructSupport":"plausible","modelId":"gap-006","phase":"supplement","careerId":"accounting","questionId":"accounting-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to prepare and analyze an organization’s financial records and reports so people can understand its money and meet reporting rules?"},{"token":"reflection-554d798d501359","response":"unsure","confidence":"low","evidence":"He copies shop shelf labels and matches entries to receipts, which shows experience with familiar details. He is less confident in formal writing in either home language and has no stated interest in proofreading other people’s language and layout; neither that confidence issue nor his receipt work resolves a desire to learn publication checking.","biographyPaths":["biography.background.cultureLanguages","biography.timeline[3].story","biography.currentLife.demonstratedSkills[0]"],"constructSupport":"unknown","modelId":"gap-006","phase":"supplement","careerId":"degree-43908100","questionId":"degree-43908100-047-domain","expanded":true,"originalPrompt":"Would you like to learn to make written material accurate and consistent by identifying errors in spelling, grammar, punctuation, arrangement, or other details before publication?"}]},"gap-013":{"version":"0.50.0","phase":"supplement","answers":[{"token":"reflection-8e9fe0145b5e9e","response":"unsure","confidence":"low","evidence":"Jalen chooses and schedules friends’ gaming sessions and settles team choices. That is a real coordination activity, but it does not establish a wish to turn a work goal into linked tasks, deadlines, staffing, and a budget, particularly when the biography leaves enjoyment of gaming versus belonging unresolved.","biographyPaths":["biography.timeline[5].story","biography.currentLife.demonstratedSkills[0]","biography.openQuestions[1]"],"constructSupport":"plausible","modelId":"gap-013","phase":"supplement","careerId":"project-management","questionId":"project-management-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to turn a work project’s goals into a plan for its people, tasks, deadlines, and budget?"},{"token":"reflection-a7df5dcece63d5","response":"unsure","confidence":"low","evidence":"He remembers friends’ schedules and resolves minor gaming-team disagreements, so coordinating familiar people can appeal. Owning delivery to a client or organization through progress checks and problems is a further responsibility for which the biography provides no chosen activity or wish.","biographyPaths":["biography.timeline[5].story","biography.currentLife.activities[0]","biography.currentLife.motivations[0]"],"constructSupport":"plausible","modelId":"gap-013","phase":"supplement","careerId":"project-management","questionId":"project-management-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to coordinate a work team, track problems and progress, and take responsibility for delivering the agreed results to a client or organization?"}]},"gap-016":{"version":"0.50.0","phase":"supplement","answers":[{"token":"reflection-0e4a5d92339d0f","response":"unsure","confidence":"low","evidence":"Wyatt can steadily unload feed beside a familiar adult and notices missing usual supplies. That is experience executing a physical routine, not evidence that he wants to plan organizational quantities, storage, arrival times, and destinations. His absence of an independently chosen plan leaves the reflection open.","biographyPaths":["biography.timeline[6].story","biography.currentLife.activities[1]","biography.currentLife.demonstratedSkills[2]","biography.currentLife.ambitions[1]"],"constructSupport":"plausible","modelId":"gap-016","phase":"supplement","careerId":"logistics","questionId":"logistics-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to plan how an organization’s supplies or products get to the right place at the right time?"},{"token":"reflection-09dc2c9d450d79","response":"unsure","confidence":"low","evidence":"His feed-store work is familiar unloading with clear directions, and he avoids approaching strangers about openings. Neither establishes dislike of delivery coordination, but there is no expressed interest in negotiating changed commitments among suppliers, transporters, and customers.","biographyPaths":["biography.timeline[6].story","biography.currentLife.demonstratedSkills[0]","biography.currentLife.avoids[2]"],"constructSupport":"unknown","modelId":"gap-016","phase":"supplement","careerId":"logistics","questionId":"logistics-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to coordinate suppliers, transport, and customers when delivery plans change or something goes wrong?"}]},"gap-021":{"version":"0.50.0","phase":"supplement","answers":[{"token":"reflection-d9dd6e4d7cb71e","response":"unsure","confidence":"low","evidence":"Audrey likes planning social outings and coordinates invitations, while tracking deadlines with calendar support. These are possible starting points for project planning, but her minor club duties and lack of sustained self-directed projects do not establish interest in a whole work plan including staffing, dependencies, and budget.","biographyPaths":["biography.currentLife.enjoys[3]","biography.currentLife.demonstratedSkills[0]","biography.currentLife.demonstratedSkills[1]","biography.timeline[4].story","biography.currentLife.unfamiliarActivities[3]"],"constructSupport":"plausible","modelId":"gap-021","phase":"supplement","careerId":"project-management","questionId":"project-management-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to turn a work project’s goals into a plan for its people, tasks, deadlines, and budget?"},{"token":"reflection-e120edcc177e7f","response":"unsure","confidence":"low","evidence":"Maintaining group chats and organizing responses show that Audrey does coordinate people she knows. She cannot identify what she enjoyed producing in a polished presentation and has only limited committee duties, so sustained delivery responsibility to a client through setbacks is unresolved rather than inferred from her social coordination.","biographyPaths":["biography.timeline[4].story","biography.timeline[6].story","biography.currentLife.activities[0]","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"gap-021","phase":"supplement","careerId":"project-management","questionId":"project-management-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to coordinate a work team, track problems and progress, and take responsibility for delivering the agreed results to a client or organization?"},{"token":"reflection-d61d38f4cdb608","response":"unsure","confidence":"low","evidence":"She enjoys arranging outings and has some school social-committee involvement. There is no stated wish to check supplier promises, reconcile event bills, or own the promised service result; independent budgeting is unfamiliar, which signals an open learning question rather than a reason to reject it.","biographyPaths":["biography.currentLife.enjoys[3]","biography.currentLife.activities[0]","biography.currentLife.unfamiliarActivities[1]"],"constructSupport":"plausible","modelId":"gap-021","phase":"supplement","careerId":"degree-13112100","questionId":"degree-13112100-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to manage event commitments and bills while making sure suppliers and staff deliver the arrangements promised to a client?"}]},"gap-023":{"version":"0.50.0","phase":"supplement","answers":[{"token":"reflection-36a53ccf61c60f","response":"unsure","confidence":"low","evidence":"Valentina compares resale prices, writes clear item descriptions, and records costs and proceeds for her monthly listings. Those choices connect to explaining an item’s value, but documenting assumptions and uncertainty for someone’s consequential financial decision is not established by her small sales.","biographyPaths":["biography.timeline[4].story","biography.timeline[6].story","biography.currentLife.enjoys[2]","biography.currentLife.demonstratedSkills[0]","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"gap-023","phase":"supplement","careerId":"degree-13202200","questionId":"degree-13202200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to prepare a clearly documented valuation and explain its assumptions to people who may rely on it for important financial decisions?"},{"token":"reflection-346e7155ad2138","response":"unsure","confidence":"low","evidence":"She likes organizing actual sale information in inventory tables and keeps proceeds records. That is evidence for practical information organization, but it does not show that setting confidentiality, access, retention, and secure-disposal rules for shared organizational records would interest her.","biographyPaths":["biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"gap-023","phase":"supplement","careerId":"degree-15129903","questionId":"degree-15129903-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to coordinate document-handling rules that balance useful access with confidentiality, retention duties, and secure disposal when records are no longer needed?"}]},"legacy-015":{"version":"0.50.0","phase":"legacy","answers":[{"token":"reflection-c5b25f424c5149","response":"unsure","confidence":"low","evidence":"Cameron enjoys diagnosing faults, checks fixes, and wants to compare vehicle and machinery training. Curiosity about how larger machines work is a possible bridge, but their chosen activity remains repair; there is no stated wish to develop new structures or power and movement systems.","biographyPaths":["biography.timeline[4].story","biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.enjoys[0]"],"constructSupport":"plausible","modelId":"legacy-015","phase":"legacy","careerId":"degree-17214102","questionId":"degree-17214102-047-domain","expanded":true,"originalPrompt":"Would you like to learn to develop new or improved vehicle systems, such as their structure, power, or movement, rather than mainly repairing existing vehicles?"},{"token":"reflection-60ab0a71184023","response":"unsure","confidence":"low","evidence":"A failed bicycle repair led Cameron to value final testing, and they ask what engine checks rule out. That supports interest in checking reliability of a repair, but coordinating new vehicle design changes across specialists and whole-vehicle requirements remains a plausible transfer only.","biographyPaths":["biography.timeline[3].story","biography.timeline[4].story","biography.currentLife.enjoys[1]"],"constructSupport":"plausible","modelId":"legacy-015","phase":"legacy","careerId":"degree-17214102","questionId":"degree-17214102-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to coordinate design changes with other technical specialists and check their effects on vehicle safety, reliability, and the requirements for the whole vehicle?"}]},"legacy-017":{"version":"0.50.0","phase":"legacy","answers":[{"token":"reflection-1ebdd339ebe58a","response":"unsure","confidence":"low","evidence":"Rowan asks people about preferences, sketches visual changes, and noticed that a pictured hairstyle could fail someone’s daily routine. Those choices support balancing appearance and use, but production specifications about materials, fit, and construction so other people can manufacture the design are not yet a supported interest.","biographyPaths":["biography.timeline[1].story","biography.timeline[3].story","biography.timeline[4].story","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"legacy-017","phase":"legacy","careerId":"degree-27102200","questionId":"degree-27102200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to communicate clear production details and balance the intended look with fit, materials, and practical constraints so others can make the design?"},{"token":"reflection-11ace0895b946e","response":"unsure","confidence":"low","evidence":"Their repeated outfit and hairstyle sketches show a sustained visual interest, including possibilities for fictional characters. The sketches respond to individual preferences; there is no stated goal to develop a coherent personal collection or make finishing and presentation choices for its audience.","biographyPaths":["biography.timeline[1].story","biography.timeline[3].story","biography.currentLife.activities[0]","biography.selfDescription"],"constructSupport":"plausible","modelId":"legacy-017","phase":"legacy","careerId":"degree-27101300","questionId":"degree-27101300-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to develop a coherent personal body of artwork and make considered choices about how it is finished, presented, or adapted for an audience?"}]},"legacy-019":{"version":"0.50.0","phase":"legacy","answers":[{"token":"reflection-53dfc2d8b60803","response":"yes","confidence":"medium","evidence":"Jordan became curious about first aid, asked what training would permit real emergency responsibility, repeatedly chose instructor-led scenarios, and now investigates EMT training. The explicit appeal of immediate trained care and team procedures supports learning to recognize changing clinical need and select an appropriate response within her role; her uncertainty is about experiencing a real crisis, not a lack of desire to learn that care.","biographyPaths":["biography.timeline[4].story","biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.enjoys[0]","biography.currentLife.ambitions[0]","biography.selfDescription"],"constructSupport":"direct","modelId":"legacy-019","phase":"legacy","careerId":"degree-29114101","questionId":"degree-29114101-047-method","expanded":true,"originalPrompt":"Would you like to learn to interpret changing symptoms and clinical findings to recognize instability and choose appropriate immediate care within the clinical responsibilities of your role?"},{"token":"reflection-4a0a4247ec68a7","response":"unsure","confidence":"low","evidence":"Her repeated first-aid practice and wish to investigate EMT training support learning immediate care. They do not specifically reveal whether she wants to interpret trends across patient measurements and test results, as opposed to carrying out coordinated practiced procedures, so this narrower clinical-information method remains tentative.","biographyPaths":["biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.enjoys[1]","biography.currentLife.enjoys[2]"],"constructSupport":"plausible","modelId":"legacy-019","phase":"legacy","careerId":"degree-29114103","questionId":"degree-29114103-047-method","expanded":true,"originalPrompt":"Would you like to learn to interpret changes in a patient's measurements and test results to recognize deterioration and work out what immediate care is needed?"},{"token":"reflection-510a27a8723137","response":"unsure","confidence":"low","evidence":"Jordan likes immediate trained care, repeated scenarios, and team procedures, so prompt response within a care team has support. The continuing prescribed-treatment and sustained nursing-care responsibility for a critically ill person goes beyond her stated first-aid and EMT curiosity; preferring immediate care to years of follow-up does not itself prove she would reject continuous critical care.","biographyPaths":["biography.timeline[5].story","biography.currentLife.activities[0]","biography.currentLife.ambitions[0]","biography.selfDescription"],"constructSupport":"plausible","modelId":"legacy-019","phase":"legacy","careerId":"degree-29114103","questionId":"degree-29114103-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to provide prescribed treatments and respond promptly to dangerous changes while coordinating continuous nursing care for patients in a critical condition?"}]},"legacy-022":{"version":"0.50.0","phase":"legacy","answers":[{"token":"reflection-c10a9d218ce304","response":"unsure","confidence":"low","evidence":"Sage enjoys accurate appointment lists and corrected duplicate sign-ups with an adult’s help while avoiding embarrassment. That gives a modest connection to careful records, but does not show an interest in deciding confidential access, retention duties, and secure disposal across a document lifecycle.","biographyPaths":["biography.timeline[4].story","biography.timeline[5].story","biography.currentLife.enjoys[0]"],"constructSupport":"plausible","modelId":"legacy-022","phase":"legacy","careerId":"degree-15129903","questionId":"degree-15129903-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to coordinate document-handling rules that balance useful access with confidentiality, retention duties, and secure disposal when records are no longer needed?"},{"token":"reflection-daacc59af108dd","response":"unsure","confidence":"low","evidence":"She repeatedly chooses useful scheduling and clear messages, helped a class know where to go, and finds office or service settings appealing. These support administrative help itself, but supervising support staff and controlling service budgets while owning departmental service outcomes are additional responsibilities with no stated preference.","biographyPaths":["biography.timeline[2].story","biography.timeline[3].story","biography.timeline[5].story","biography.currentLife.motivations[1]"],"constructSupport":"plausible","modelId":"legacy-022","phase":"legacy","careerId":"degree-11301200","questionId":"degree-11301200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to oversee support staff and service budgets while making sure departments receive reliable administrative help?"}]},"new049-007":{"version":"0.50.0","phase":"development049","answers":[{"token":"reflection-575e0b2d3aa7b4","response":"unsure","confidence":"low","evidence":"Gabriel compares competing accounts about community policy, separates factual disputes from priorities, and checks original documents. That supports systematic scrutiny of existing claims, but it does not establish a wish to design systematic information gathering from a group about its experiences rather than work mainly with written arguments and sources.","biographyPaths":["biography.timeline[3].story","biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.activities[1]"],"constructSupport":"plausible","modelId":"new049-007","phase":"development049","careerId":"degree-19302200","questionId":"degree-19302200-047-domain","expanded":true,"originalPrompt":"Would you like to learn to investigate what a group of people thinks, experiences, or does by gathering information systematically rather than relying on anecdotes?"},{"token":"reflection-41ef43955ab86e","response":"unsure","confidence":"low","evidence":"He checks quotations, seeks missing facts, and dislikes careless claims in his policy writing. These are substantial evidence-oriented habits, but no financial or property investigation interest is stated; the possible explanation-checking transfer does not supply that specialized subject preference.","biographyPaths":["biography.timeline[6].story","biography.currentLife.demonstratedSkills[1]","biography.currentLife.motivations[2]","biography.selfDescription"],"constructSupport":"plausible","modelId":"new049-007","phase":"development049","careerId":"degree-13209904","questionId":"degree-13209904-047-domain","expanded":true,"originalPrompt":"Would you like to learn to investigate suspected deception involving money or property and work out what happened from evidence rather than assumptions?"}]},"life-008":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-0417e31cf91b41","response":"unsure","confidence":"low","evidence":"Caleb has drawn beetle anatomy, repainted stage scenery, and enjoyed making varied wooden objects. These supply visual-making interests, but none shows wanting to build moving characters through successive drawings or digital models. Disliking identical sales orders does not by itself imply disliking animation revisions.","biographyPaths":["biography.timeline[2].story","biography.timeline[3].story","biography.timeline[5].story","biography.selfDescription"],"constructSupport":"plausible","modelId":"life-008","phase":"holdout","careerId":"animation","questionId":"animation-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to create drawings or digital models that become moving characters, objects, or visual effects for animation as a regular part of your work?"},{"token":"reflection-6ff63a2017604b","response":"unsure","confidence":"low","evidence":"His choir and class-play participation and memory for performance cues connect him with staged action. Repainting scenery is also a concrete visual activity, but there is no stated interest in planning animated movement and repeatedly changing its timing to clarify an action for viewers.","biographyPaths":["biography.timeline[4].story","biography.timeline[5].story","biography.currentLife.demonstratedSkills[2]"],"constructSupport":"plausible","modelId":"life-008","phase":"holdout","careerId":"animation","questionId":"animation-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to plan animated scenes and revise their movement, timing, or appearance to make the intended action clear as a regular part of your work?"}]},"life-010":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-d179fc59a3e2e2","response":"unsure","confidence":"low","evidence":"Devin has chosen community-center scheduling and event setup, enjoys planning table layouts, and likes seeing a plan function. Those show useful coordination in group settings, but overseeing support staff and controlling a service budget while owning departmental support outcomes are additional responsibilities without a stated preference.","biographyPaths":["biography.timeline[4].story","biography.timeline[5].story","biography.currentLife.activities[0]","biography.currentLife.enjoys[1]","biography.currentLife.motivations[1]"],"constructSupport":"plausible","modelId":"life-010","phase":"holdout","careerId":"degree-11301200","questionId":"degree-11301200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to oversee support staff and service budgets while making sure departments receive reliable administrative help?"},{"token":"reflection-dbe480da9e913b","response":"unsure","confidence":"low","evidence":"He helps a coach settle scheduling disagreements and patiently reviews chess mistakes with another person. These offer a possible interest in structured resolution, but there is no evidence that conducting fair proceedings and documenting the distinction between agreement and authorized decision is itself an activity he wants to learn.","biographyPaths":["biography.timeline[1].story","biography.timeline[4].story","biography.currentLife.demonstratedSkills[2]"],"constructSupport":"plausible","modelId":"life-010","phase":"holdout","careerId":"degree-23102200","questionId":"degree-23102200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to conduct fair proceedings and clearly document the outcome while respecting whether the process calls for agreement or a decision?"}]},"life-017":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-5269e7a827adff","response":"unsure","confidence":"low","evidence":"Nadia uses English and Spanish and has interviewed residents whose memories differed. Her enjoyment is specifically historical fact checking and verifying stories against documents; using two languages and listening carefully do not establish a wish to relay someone else’s message accurately between languages.","biographyPaths":["biography.background.cultureLanguages","biography.timeline[5].story","biography.currentLife.enjoys[0]","biography.currentLife.demonstratedSkills[0]"],"constructSupport":"plausible","modelId":"life-017","phase":"holdout","careerId":"interpreting","questionId":"interpreting-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to convey someone’s spoken or signed message accurately from one language into another?"},{"token":"reflection-a73299dc066a08","response":"unsure","confidence":"low","evidence":"Her neighborhood-history interviews and stated enjoyment of checking confident stories show attention to what an account means and whether it holds up. Her early directing interest also involved intended dramatic effect. These could transfer to interpreting context, but neither states an interest in preserving another speaker’s intent and tone through translation.","biographyPaths":["biography.timeline[0].story","biography.timeline[5].story","biography.selfDescription","biography.background.cultureLanguages"],"constructSupport":"plausible","modelId":"life-017","phase":"holdout","careerId":"interpreting","questionId":"interpreting-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to work out meaning and context across languages so the translated message preserves the speaker’s intent and tone?"}]},"life-019":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-f43386fdb621d6","response":"unsure","confidence":"low","evidence":"Zara experimented with drawer-label wording to help people find things and uses English and Arabic at home. That supplies attention to clear words and language familiarity, but her chosen projects do not establish an interest in accurately conveying another person’s spoken or signed message across languages. Her treatment and variable energy do not determine this preference.","biographyPaths":["biography.timeline[0].story","biography.background.cultureLanguages","biography.currentLife.demonstratedSkills[0]"],"constructSupport":"plausible","modelId":"life-019","phase":"holdout","careerId":"interpreting","questionId":"interpreting-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to convey someone’s spoken or signed message accurately from one language into another?"},{"token":"reflection-75697edbc94c14","response":"unsure","confidence":"low","evidence":"Zara wrote mysteries with negotiated endings and enjoys thoughtful story construction, while her label experiments considered how wording affects understanding. These are possible links to intent and ambiguity, but no desire to work out meaning and tone across languages is stated; current uncertainty about activities does not supply either a yes or a no.","biographyPaths":["biography.timeline[0].story","biography.timeline[2].story","biography.currentLife.demonstratedSkills[2]","biography.timeline[6].story"],"constructSupport":"plausible","modelId":"life-019","phase":"holdout","careerId":"interpreting","questionId":"interpreting-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to work out meaning and context across languages so the translated message preserves the speaker’s intent and tone?"}]},"life-046":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-35a1f7e588a7cd","response":"unsure","confidence":"low","evidence":"Linh asked about bare riverbanks, repeated an erosion demonstration, observes bank changes, and volunteers at cleanups. These show interest in environmental processes and places. They do not establish a wish to develop and communicate research conclusions about relationships between places, with alternative explanations and evidentiary limits; her own open question still asks whether systematic field observation appeals apart from volunteering.","biographyPaths":["biography.timeline[1].story","biography.timeline[5].story","biography.currentLife.demonstratedSkills[0]","biography.openQuestions[1]"],"constructSupport":"plausible","modelId":"life-046","phase":"holdout","careerId":"degree-19309200","questionId":"degree-19309200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to communicate a research-based explanation of relationships between places, including the evidence and limits behind the geographic conclusions?"}]},"life-059":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-27f86584073760","response":"unsure","confidence":"low","evidence":"Wyatt likes quiet outdoor space, has sorted supplies, and follows detailed sequences once started. These could make orderly sample handling approachable, but they do not show interest in biological material or collecting and preparing it for scientists. Early questions while following the groundskeeper do not establish that specific research interest.","biographyPaths":["biography.timeline[0].story","biography.timeline[5].story","biography.currentLife.enjoys[2]","biography.currentLife.demonstratedSkills[0]"],"constructSupport":"plausible","modelId":"life-059","phase":"holdout","careerId":"biological-technician","questionId":"biological-technician-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to collect and prepare biological samples, such as plants, water, or animal material, to help scientists study living things?"},{"token":"reflection-65a9d0a9c8669c","response":"unsure","confidence":"low","evidence":"He became interested when a documented recipe variation changed biscuit texture, and now compares variations while repeating familiar baking. That is concrete curiosity about method and outcome, but applying it to biological experiments and maintaining observations for a research team remains a possible transfer without supported interest in the biological subject.","biographyPaths":["biography.timeline[4].story","biography.currentLife.enjoys[0]","biography.currentLife.demonstratedSkills[1]"],"constructSupport":"plausible","modelId":"life-059","phase":"holdout","careerId":"biological-technician","questionId":"biological-technician-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to carry out biological experiments carefully, observe what happens, and record results for a research team?"}]},"life-097":{"version":"0.50.0","phase":"holdout","answers":[{"token":"reflection-d802bf4b31c6a6","response":"unsure","confidence":"low","evidence":"Jonas makes paper sculptures and learned simple video editing, so image construction and moving media are not wholly absent. He preferred recording real plant growth to entertaining clips, however, and no activity or wish indicates creating drawings or digital models into animated characters or effects. That preference is not a stated rejection of animation.","biographyPaths":["biography.timeline[2].story","biography.timeline[3].story","biography.currentLife.enjoys[2]"],"constructSupport":"plausible","modelId":"life-097","phase":"holdout","careerId":"animation","questionId":"animation-interest-044-1","expanded":false,"originalPrompt":"Would you like to learn to create drawings or digital models that become moving characters, objects, or visual effects for animation as a regular part of your work?"},{"token":"reflection-ac66ed34215b69","response":"unsure","confidence":"low","evidence":"His video experience concerns recording changing plants, and he willingly repeats observations of living things. Those choices support patient observation of real change, not necessarily planning a fictional moving scene and repeatedly revising its visual timing. There is no stated wish for that particular creative process.","biographyPaths":["biography.timeline[2].story","biography.currentLife.activities[0]","biography.selfDescription"],"constructSupport":"plausible","modelId":"life-097","phase":"holdout","careerId":"animation","questionId":"animation-interest-044-2","expanded":false,"originalPrompt":"Would you like to learn to plan animated scenes and revise their movement, timing, or appearance to make the intended action clear as a regular part of your work?"}]},"new049-020":{"version":"0.50.0","phase":"holdout049","answers":[{"token":"reflection-aab8b41708e658","response":"unsure","confidence":"low","evidence":"Miles voluntarily persists with physics, enjoys clarifying motion problems, and compares experiments with predictions. These support physical-science curiosity despite uneven performance, but there is no stated astronomy interest or desire to design and communicate an investigation using limited astronomical observations. Independent-investigation unfamiliarity does not establish dislike or inability to learn it.","biographyPaths":["biography.timeline[4].story","biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.enjoys[1]","biography.currentLife.unfamiliarActivities[0]"],"constructSupport":"plausible","modelId":"new049-020","phase":"holdout049","careerId":"degree-19201100","questionId":"degree-19201100-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to design and communicate a defensible investigation of an astronomical question, including uncertainty and the limits of available observations?"},{"token":"reflection-72ec2d2b28e404","response":"unsure","confidence":"low","evidence":"He enjoys tracing mistakes in physical reasoning, comparing an experiment with his prediction, and asking specific questions about a mistaken step. That provides a possible basis for examining assumptions, but does not establish wanting to document research methods and uncertainties for other people to inspect or repeat. His dislike of report formatting and reliance on a partner for some writing concern parts of reporting, without proving dislike of this substantive communication responsibility.","biographyPaths":["biography.timeline[5].story","biography.currentLife.enjoys[1]","biography.currentLife.demonstratedSkills[2]","biography.currentLife.avoids[1]","biography.currentLife.struggles[1]"],"constructSupport":"plausible","modelId":"new049-020","phase":"holdout049","careerId":"degree-19201200","questionId":"degree-19201200-047-responsibility","expanded":true,"originalPrompt":"Would you like to learn to report physical research with enough detail about assumptions and uncertainty for others to examine or repeat the investigation?"}]},"diag049-003":{"version":"0.50.0","phase":"diagnostic049","answers":[{"token":"reflection-575e0b2d3aa7b4","response":"unsure","confidence":"low","evidence":"Gabriel compares competing accounts about community policy, separates factual disputes from priorities, and checks original documents. That supports systematic scrutiny of existing claims, but it does not establish a wish to design systematic information gathering from a group about its experiences rather than work mainly with written arguments and sources.","biographyPaths":["biography.timeline[3].story","biography.timeline[5].story","biography.timeline[6].story","biography.currentLife.activities[1]"],"constructSupport":"plausible","modelId":"new049-007","phase":"development049","careerId":"degree-19302200","questionId":"degree-19302200-047-domain","expanded":true,"originalPrompt":"Would you like to learn to investigate what a group of people thinks, experiences, or does by gathering information systematically rather than relying on anecdotes?"},{"token":"reflection-41ef43955ab86e","response":"unsure","confidence":"low","evidence":"He checks quotations, seeks missing facts, and dislikes careless claims in his policy writing. These are substantial evidence-oriented habits, but no financial or property investigation interest is stated; the possible explanation-checking transfer does not supply that specialized subject preference.","biographyPaths":["biography.timeline[6].story","biography.currentLife.demonstratedSkills[1]","biography.currentLife.motivations[2]","biography.selfDescription"],"constructSupport":"plausible","modelId":"new049-007","phase":"development049","careerId":"degree-13209904","questionId":"degree-13209904-047-domain","expanded":true,"originalPrompt":"Would you like to learn to investigate suspected deception involving money or property and work out what happened from evidence rather than assumptions?"}],"inheritedFrom":"new049-007"}};
